albums = FileAttachment("data/queen_albums.csv").csv({ typed: true })

viewof selected = Inputs.select(albums, {
  label: "Select an album:",
  format: d =&gt; `${d.year} - ${d.title}`
})

html`&lt;div style="margin-top: 20px;"&gt;
  &lt;img src="data/${selected.cover_filename}" alt="${selected.title}" style="max-width: 400px; width: 100%; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"&gt;
&lt;/div&gt;`
